body.query:
query ($h: Int!) { block(offset: { height: $h }) { 
  height hash timestamp parent { hash }
  transactions {
    __typename id hash raw
    contractActions { __typename address }
    ... on RegularTransaction { transactionResult { status segments { id success } } }
  }
 } }

